CREATE TRIGGER prose_section_ad AFTER DELETE ON prose_section BEGIN
        DELETE FROM prose_section_fts WHERE rowid = old.id;
    END

CREATE TRIGGER trg_narrative_telling_ai AFTER INSERT ON narrative_claim_telling
BEGIN
  INSERT INTO narrative_claim_change (claim_id, passage_id, change_date, change_kind, passage_after, chapter_id, section_id, note, basis, provenance, created_by)
  SELECT NEW.claim_id, NEW.passage_id, substr(NEW.created_at, 1, 10), 'telling added', p.passage_text, p.chapter_id, p.section_id, NEW.kind || COALESCE(': ' || NEW.part_told, ''), 'direct edit', 'trigger trg_narrative_telling_ai', 'trigger' FROM narrative_passage p WHERE p.id = NEW.passage_id;
  UPDATE narrative_claim SET in_narrative = (SELECT EXISTS (SELECT 1 FROM narrative_claim_telling t JOIN narrative_passage p ON p.id = t.passage_id WHERE t.claim_id = narrative_claim.id AND t.status = 'current' AND t.kind <> 'pointer' AND p.last_version IS NULL)) WHERE id = NEW.claim_id;
END

CREATE TRIGGER trg_narrative_telling_status_au AFTER UPDATE OF status ON narrative_claim_telling WHEN OLD.status IS NOT NEW.status
BEGIN
  INSERT INTO narrative_claim_change (claim_id, passage_id, change_date, change_kind, passage_before, passage_after, chapter_id, section_id, note, basis, provenance, created_by)
  SELECT NEW.claim_id, NEW.passage_id, date('now'), CASE NEW.status WHEN 'removed' THEN 'telling removed' ELSE 'telling added' END, CASE NEW.status WHEN 'removed' THEN p.passage_text END, CASE NEW.status WHEN 'removed' THEN NULL ELSE p.passage_text END, p.chapter_id, p.section_id, 'status: ' || OLD.status || ' -> ' || NEW.status, 'direct edit', 'trigger trg_narrative_telling_status_au', 'trigger' FROM narrative_passage p WHERE p.id = NEW.passage_id;
  UPDATE narrative_claim SET in_narrative = (SELECT EXISTS (SELECT 1 FROM narrative_claim_telling t JOIN narrative_passage p ON p.id = t.passage_id WHERE t.claim_id = narrative_claim.id AND t.status = 'current' AND t.kind <> 'pointer' AND p.last_version IS NULL)) WHERE id = NEW.claim_id;
END

CREATE TRIGGER trg_narrative_telling_kind_au AFTER UPDATE OF kind, part_told ON narrative_claim_telling WHEN OLD.kind IS NOT NEW.kind OR OLD.part_told IS NOT NEW.part_told
BEGIN
  INSERT INTO narrative_claim_change (claim_id, passage_id, change_date, change_kind, passage_after, chapter_id, section_id, note, basis, provenance, created_by)
  SELECT NEW.claim_id, NEW.passage_id, date('now'), 'telling changed', p.passage_text, p.chapter_id, p.section_id, 'kind: ' || OLD.kind || ' -> ' || NEW.kind || '; part: ' || COALESCE(OLD.part_told, '-') || ' -> ' || COALESCE(NEW.part_told, '-'), 'direct edit', 'trigger trg_narrative_telling_kind_au', 'trigger' FROM narrative_passage p WHERE p.id = NEW.passage_id;
  UPDATE narrative_claim SET in_narrative = (SELECT EXISTS (SELECT 1 FROM narrative_claim_telling t JOIN narrative_passage p ON p.id = t.passage_id WHERE t.claim_id = narrative_claim.id AND t.status = 'current' AND t.kind <> 'pointer' AND p.last_version IS NULL)) WHERE id = NEW.claim_id;
END

CREATE TRIGGER trg_narrative_telling_ad AFTER DELETE ON narrative_claim_telling
BEGIN
  INSERT INTO narrative_claim_change (claim_id, passage_id, change_date, change_kind, passage_before, note, basis, provenance, created_by)
  SELECT OLD.claim_id, OLD.passage_id, date('now'), 'telling removed', (SELECT passage_text FROM narrative_passage WHERE id = OLD.passage_id), 'telling row deleted', 'direct edit', 'trigger trg_narrative_telling_ad', 'trigger';
  UPDATE narrative_claim SET in_narrative = (SELECT EXISTS (SELECT 1 FROM narrative_claim_telling t JOIN narrative_passage p ON p.id = t.passage_id WHERE t.claim_id = narrative_claim.id AND t.status = 'current' AND t.kind <> 'pointer' AND p.last_version IS NULL)) WHERE id = OLD.claim_id;
END
